    std::vector<int> levels{100, 101, 102};
    const std::vector<int>& get() const { return levels; }
};

Book load_book() { return Book{}; }

int main() {
    long sum = 0;
    for (auto book = load_book(); int px : book.get())   // C++20 init-statement owns it
        sum += px;
    std::cout << sum << '\n';                             // 303
}
```

