#include <iostream>
#include <memory>
#include <string>

struct Button {
    std::string name;
    ~Button() { std::cout << "~Button\n"; }
};

int main() {
    std::function<void()> handler;
    {
        auto button = std::make_shared<Button>();
        button->name = "ok";
        handler = [w = std::weak_ptr<Button>(button)] {
            if (auto b = w.lock()) std::cout << b->name << '\n';
            else std::cout << "button gone\n";
        };
        handler();          // ok
    }                       // ~Button
    handler();              // button gone
}
```

