              << "stateless functor: " << sizeof(FilePtr) << '\n'
              << "lambda:            " << sizeof(std::unique_ptr<F, decltype(lam)>) << '\n'
              << "function pointer:  " << sizeof(std::unique_ptr<F, int (*)(F*)>) << '\n'
              << "stateful functor:  " << sizeof(std::unique_ptr<F, Tagged>) << '\n'
