int main() {
    std::pmr::monotonic_buffer_resource r1, r2;
    std::pmr::vector<int> a({1, 2, 3}, &r1);

    std::pmr::vector<int> copy(a);                   // copy construction
    std::pmr::vector<int> copy2(a, &r2);             // allocator-extended copy
    std::pmr::vector<int> target(&r2);
