    std::vector<int> v{100, 200, 300, 400};
    std::size_t idx = 2;              // an index survives if you adjust it
    auto pos = v.insert(v.begin(), 50);
    if (pos - v.begin() <= static_cast<std::ptrdiff_t>(idx)) ++idx;
    std::cout << v[idx] << '\n';      // 300
}
```

