#include <string>
#include <string_view>

int main() {
    std::string record = "instrument-identifier-0000000042:active";
    std::string_view whole = record;
    std::string_view name = whole.substr(0, whole.find(':'));   // view of record
    std::cout << '[' << name << "]\n";
}
```

