#include <iostream>
#include <variant>

int main() {
    long raw_qty = 250;
    std::variant<int, double> qty{std::in_place_type<double>, raw_qty};
    std::cout << qty.index() << ' ' << std::get<double>(qty) << '\n';   // 1 250
}
```

