#include <iostream>
#include <string>
#include <type_traits>
#include <variant>

int main() {
    std::variant<int, std::string> v = 5;
    auto doubled = std::visit([](const auto& x) -> std::string {
        if constexpr (std::is_same_v<std::decay_t<decltype(x)>, int>)
            return std::to_string(x + x);
        else
            return x + x;
    }, v);
    std::cout << doubled << '\n';                    // 10
}
```

