    const std::size_t n = v.size();
    v.reserve(2 * n);
    for (std::size_t i = 0; i < n; ++i)
        v.push_back(v[i]);           // index is re-evaluated, never stale
    for (int x : v) std::cout << x << ' ';
    std::cout << '\n';               // 1 2 3 1 2 3
}
```

