constexpr std::uint64_t fnv1a(std::string_view s) {   // usable at run time too
    std::uint64_t h = 1469598103934665603ull;           // FNV-1a 64-bit offset basis
    for (char c : s) { h ^= static_cast<unsigned char>(c); h *= 1099511628211ull; }
    return h;
}

// compile time only:
consteval std::uint64_t msg_id(std::string_view s) { return fnv1a(s); }

struct Symbol {
    char code[8]{};
    consteval Symbol(const char* s) {
        int n = 0;
        for (; s[n] != '\0'; ++n) {
            if (n >= 7 || s[n] < 'A' || s[n] > 'Z')
                throw "invalid symbol";      // becomes a compile error
            code[n] = s[n];
        }
    }
};

const char* dispatch(std::string_view name) {
    switch (fnv1a(name)) {
        case msg_id("NewOrder"): return "handle new order";
        case msg_id("Cancel"):   return "handle cancel";
        default:                 return "unknown";
    }
}

int main() {
    constexpr Symbol s = "ABC";
    // constexpr Symbol bad = "abc1";
    //   error: expression '<throw-expression>' is not a constant expression
    std::printf("%s | %s | %s\n", dispatch("Cancel"), dispatch("Heartbeat"), s.code);
}

// C++23: g++ -std=c++23 (GCC 12+)
#include <cstdio>

consteval int checked_scale(int x) {
    if (x > 1'000'000) throw "scale overflow";       // compile-time error
    return x * 100;
}

constexpr int scale(int x) {
    if consteval {
        return checked_scale(x);        // allowed: immediate function context
    } else {
        return x * 100;                 // run-time path (intrinsics, logging, ...)
    }
}

int main(int argc, char**) {
    constexpr int a = scale(25);        // compile time, checked
    int b = scale(argc);                // run time
    std::printf("%d %d\n", a, b);
}

// C++20 library feature (constexpr std::vector): GCC 12+; checked with GCC 13 -std=c++23
#include <algorithm>
#include <array>
#include <cstdio>
#include <vector>

constexpr std::vector<int> primes_below(int limit) {
    std::vector<int> out;
    for (int n = 2; n < limit; ++n) {
        bool prime = true;
        for (int d = 2; d * d <= n; ++d)
            if (n % d == 0) { prime = false; break; }
        if (prime) out.push_back(n);
    }
    return out;
}

constexpr std::size_t count = primes_below(50).size();     // vector freed here

constexpr std::array<int, count> prime_table = [] {
    std::array<int, count> a{};
    auto v = primes_below(50);
    std::reverse(v.begin(), v.end());                          // constexpr since C++20
    std::copy(v.begin(), v.end(), a.begin());
    return a;
}();

int main() {
    std::printf("%zu primes, largest %d, smallest %d\n",
                prime_table.size(), prime_table.front(), prime_table.back());
}

#include <cstdint>
#include <cstdio>

class Price {
    std::int64_t ticks_;                       // 1 tick = 0.0001
public:
    static constexpr std::int64_t scale = 10'000;
    constexpr explicit Price(std::int64_t ticks) : ticks_(ticks) {}
    constexpr std::int64_t ticks() const { return ticks_; }
    constexpr Price operator+(Price o) const { return Price(ticks_ + o.ticks_); }
    constexpr bool operator<(Price o) const { return ticks_ < o.ticks_; }
};

constexpr Price operator""_px(long double v) {
    return Price(static_cast<std::int64_t>(v * Price::scale + 0.5L));
}

constexpr Price tick_size = 0.0005_px;
constexpr Price limit = 101.25_px + tick_size;

static_assert(limit.ticks() == 1'012'505);
static_assert(sizeof(Price) == 8);             // layout assumption checked at build time
static_assert(tick_size < limit);

int main() {
    Price p(1'012'000);                          // run-time object, same type
    std::printf("%lld %d\n", static_cast<long long>((p + tick_size).ticks()), p < limit);
}

interview_qa.explanation:
```cpp
#include <array>
#include <cstdint>
#include <iostream>

constexpr std::array<std::uint8_t, 256> make_table() {
    std::array<std::uint8_t, 256> t{};
    for (int i = 0; i < 256; ++i) t[i] = static_cast<std::uint8_t>(i * 7);
    return t;
}

bool local_same(int depth, const void* outer) {
    constexpr auto table = make_table();           // values: compile time
    if (depth == 0) return local_same(1, &table);  // object: one per call
    return outer == &table;
}

bool static_same(int depth, const void* outer) {
    static constexpr auto table = make_table();    // one object in .rodata
    if (depth == 0) return static_same(1, &table);
    return outer == &table;
}

int main() {
    std::cout << std::boolalpha << local_same(0, nullptr) << ' '
              << static_same(0, nullptr) << '\n';   // false true
}
```
- Two active calls see two different local tables (`false`) but the same static one (`true`): the local is a new object per call, exactly like any other local variable.
- Cost, checked in the assembly (GCC 11 and 13, x86-64): for `int lookup(int i) { constexpr auto t = make_table(); return t[i & 255]; }` even `-O2` rebuilds the 256-byte table on the stack on every call (32 eight-byte immediate stores on GCC 11, 16-byte copies from `.rodata` on GCC 13). With `static constexpr` the function is one address load plus one byte load.
- No thread-safety cost: a `static` local with a constant initializer is initialized at compile time, so there is no guard variable or lock.
- Inside a `constexpr` function a `static constexpr` local needs C++23 (P2647); in C++20 put the table at namespace scope (`inline constexpr auto table = make_table();` in a header).
- ❌ Common wrong answer: "constexpr means it lives in the binary and costs nothing at run time." Only the values are fixed; storage duration still follows the usual rules.
- ✅ What a strong answer adds: the namespace-scope version has its own trap: a `constexpr` variable in a header has internal linkage, so every translation unit gets its own copy (two addresses, verified with two TUs on GCC 11); `inline constexpr` (C++17) gives one object for the whole program.

