#include <future>
#include <iostream>
#include <thread>

int main() {
    std::cout << "start\n";
    auto fut = std::async(std::launch::async, [] {
        std::this_thread::sleep_for(std::chrono::milliseconds(200));
        std::cout << "task finished\n";
    });
    std::cout << "after async\n"; // now printed first (task sleeps 200 ms)
    fut.get();
}
```

