    std::vector<std::thread> threads;
    for (int i = 0; i < 4; ++i) {
        threads.emplace_back([i, &m] {        // copy of i per thread
            std::lock_guard lock(m);
            std::cout << i;
        });
    }
    for (auto& t : threads) t.join();
    std::cout << '\n';                        // some permutation of 0123
}
```

