#include <iostream>
#include <mutex>
#include <thread>

std::mutex m;
int result = 0;

int main() {
    std::thread worker([] {
        std::lock_guard<std::mutex> wg(m);
        result = 42;
    });
    std::cout << "main: joining\n";
    worker.join();                          // no lock held while joining
    std::cout << "result " << result << '\n';   // result 42 (join gives happens-before)
}
```

