    auto [it, inserted] = table.try_emplace(key, 1);    // re-check under the exclusive lock
    if (inserted) std::cout << "writer: created " << key << '\n';
    return it->second;
}

int main() {
    std::cout << get_or_create("AAPL") << '\n';
}

