    // T1 starts pop: reads head and head->next, then is preempted
    Node* t1_old = head.load();          // A
    Node* t1_next = t1_old->next;        // B

    // T2 runs to completion
    Node* x = pop();                     // A
    Node* y = pop();                     // B
    y->alive = false;                    // T2 frees B
    push(x);                             // A is reused: head -> A -> C
