class Stack {
    std::atomic_flag busy_;                 // C++20: starts clear
    std::vector<int> data_;
public:
    void push(int v) {
        while (busy_.test_and_set()) {}     // spin until we own it
        data_.push_back(v);
        busy_.clear();
    }
    std::size_t size() {
        while (busy_.test_and_set()) {}
        std::size_t n = data_.size();
        busy_.clear();
        return n;
