            const int steps = (id == 2) ? 1 : 3;
            for (int s = 0; s < steps; ++s) {
                sync.arrive_and_wait();
            }
            if (id == 2) sync.arrive_and_drop();      // arrive for phase 2, leave the group
        });
    workers.clear();
    std::cout << "all done\n";                         // all done
}

